INSERT INTO IndexDist(rowId, fileId, line) SETTINGS insert_distributed_sync = 1 VALUES (1, 1, 'line1'), (2, 2, 'line2'), (3, 3, 'line3'), (4, 1, 'line4'), (5, 2, 'line5'), (6, 3, 'line6'), (7, 1, 'line7'), (8, 2, 'line8'), (9, 3, 'line9');
SYSTEM RELOAD DICTIONARY IndexDict ON CLUSTER '{cluster}'; SELECT throwIf( max(unloaded) > 0, 'IndexDict is not loaded on all cluster replicas' ) FROM ( SELECT count() AS unloaded FROM clusterAllReplicas('{cluster}', system.dictionaries) WHERE database = 'default' AND name = 'IndexDict' AND status != 'LOADED' );
